def is_safe(board, row, col, n):
    # Check this row on left side
    for i in range(row):
        if board[i] == col:
            return False
        # Check upper diagonal on left side
        if abs(board[i] - col) == abs(i - row):
            return False
    return True

def solve_nqueens_util(board, row, n, solutions):
    if row == n:
        solutions.append(board[:])
        return True  # Found one solution
    if row == 3:  # Fixed q[3]=1
        if is_safe(board, row, 1, n):
            board[row] = 1
            if solve_nqueens_util(board, row + 1, n, solutions):
                return True
            board[row] = -1
        return False
    for col in range(n):
        if is_safe(board, row, col, n):
            board[row] = col
            if solve_nqueens_util(board, row + 1, n, solutions):
                return True
            board[row] = -1
    return False

def solve_nqueens(n=9, fixed_row=3, fixed_col=1):
    board = [-1] * n
    solutions = []
    solve_nqueens_util(board, 0, n, solutions)
    return solutions[0] if solutions else None

result = solve_nqueens()
print(result)
